/// A colour as 8-bit sRGB.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Rgb(pub u8, pub u8, pub u8);

/// Parse one of the `#rrggbb` constants in this module.
pub const fn rgb(hex: &str) -> Rgb {
    let b = hex.as_bytes();
    const fn h(c: u8) -> u8 { match c { b'0'..=b'9' => c - b'0', b'a'..=b'f' => c - b'a' + 10, b'A'..=b'F' => c - b'A' + 10, _ => 0 } }
    Rgb(h(b[1]) * 16 + h(b[2]), h(b[3]) * 16 + h(b[4]), h(b[5]) * 16 + h(b[6]))
}

